(() => {
'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euro=n=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format((n||0)/100);
const when=s=>s==='start-folgt'?'Start folgt':s?new Intl.DateTimeFormat('de-DE',{dateStyle:'medium',timeStyle:s.length>10?'short':undefined}).format(new Date(s)):'—';
const decimal=n=>((n||0)/100).toFixed(2);
const demo=window.UNFALLX_DEMO_DATA||null;
let me,csrf='',cases=[],overview=null,current=null,busy=false;
const states={draft:'Entwurf',submitted:'Eingereicht',review:'In Prüfung',needs_info:'Rückfrage',accepted:'Angenommen',in_progress:'Gutachten in Arbeit',report_ready:'Gutachten freigegeben',report_sent:'Gutachten versandt',closed:'Abgeschlossen',declined:'Abgelehnt',pending:'Prüfung ausstehend',approved:'Freigeschaltet',rejected:'Abgelehnt',suspended:'Gesperrt'};
const nextStates={submitted:['review','needs_info','accepted','declined'],review:['needs_info','accepted','declined'],needs_info:['review','accepted'],accepted:['in_progress','needs_info'],in_progress:['needs_info','report_ready'],report_ready:['in_progress','report_sent'],report_sent:['closed']};
const payNames={unset:'Noch nicht vereinbart',pending_payment:'Wartet auf Zahlungseingang',payable:'Partnerrechnung möglich',invoice_received:'Partnerrechnung in Prüfung',approved:'Zur Auszahlung freigegeben',paid_out:'Auszahlung erfasst'};
function message(text,error=false){const el=$('#portal-message')||$('#auth-message');if(el){el.textContent=text;el.classList.toggle('portal-error',error);if(error)el.scrollIntoView({block:'nearest',behavior:me?.user.preferences?.reducedMotion||matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}}
async function api(path,method='GET',data,extra={}){if(demo){if(method!=='GET')throw new Error('Dies ist eine Beispielansicht. Es werden keine Daten gespeichert oder Nachrichten versandt.');return demo.read(path);}const headers={...extra};if(method!=='GET')headers['X-CSRF-Token']=csrf;let body;if(data instanceof File){body=data;}else if(data!==undefined){headers['Content-Type']='application/json';body=JSON.stringify(data);}const response=await fetch('/api/portal'+path,{method,headers,body,credentials:'same-origin',cache:'no-store'});const result=await response.json();if(!response.ok){const err=new Error(result.error||'Die Anfrage konnte nicht verarbeitet werden.');err.status=response.status;throw err;}return result;}
function values(form){const d=Object.fromEntries(new FormData(form));form.querySelectorAll('input[type=checkbox]').forEach(el=>d[el.name]=el.checked);return d;}
async function run(fn){if(busy)return;busy=true;const buttons=[...document.querySelectorAll('button[type=submit]')];buttons.forEach(b=>b.disabled=true);message('');try{await fn();}catch(e){message(e.message,true);}finally{busy=false;buttons.forEach(b=>b.disabled=false);}}
const badge=s=>`<span class="portal-badge" data-status="${esc(s)}">${esc(states[s]||s)}</span>`;
const field=(name,label,value='',type='text',required=true,max=180)=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" maxlength="${max}" ${required?'required':''}></label>`;
function heading(title,desc='',action=''){return `<div class="portal-heading"><div><span class="eyebrow">UNFALLX CONNECT</span><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>${action}</div>`;}
function empty(title,copy,action=''){return `<div class="portal-empty"><h2>${esc(title)}</h2><p>${esc(copy)}</p>${action}</div>`;}
function bindForm(id,fn){const form=document.getElementById(id);if(form)form.addEventListener('submit',e=>{e.preventDefault();run(()=>fn(values(form),form));});}
const root=$('#portal-root');if(!root)return;
function appearance(){const p=me.user.preferences||{};document.body.classList.toggle('portal-compact',!!p.compact);document.body.dataset.motion=p.reducedMotion?'off':'on';document.body.dataset.portalTheme=p.theme||'light';}

const partner=()=>me.user.role==='partner',admin=()=>me.user.role==='admin',customer=()=>me.user.role==='customer',external=()=>partner()||customer(),canCreate=()=>customer()||partner()&&me.company.status==='approved';
function navigation(){const menu=$('#portal-menu-toggle');if(menu){menu.setAttribute('aria-expanded','false');menu.textContent='Menü öffnen';$('#portal-nav').dataset.open='false';menu.onclick=()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'Menü schließen':'Menü öffnen';$('#portal-nav').dataset.open=String(open);};}const links=[['start','Übersicht'],['faelle','Fallübersicht'],['statistik','Statistiken']];if(external())links.push(['empfehlungen','Empfehlungen']);if(customer())links.push(['neu','+ Schaden aufnehmen']);if(partner())links.push(['neu','+ Neuer Fall'],['abrechnung','Abrechnung'],['firma','Meine Firma']);if(admin())links.push(['partner','Partnerfirmen'],['team','Internes Team'],['bildung','Bildungsanmeldungen'],['provisionen','Provisionen'],['versand','E-Mail-Versand'],['abrechnung','Abrechnung']);links.push(['einstellungen','Einstellungen'],['hilfe','Hilfe']);$('#portal-nav').innerHTML=links.map(([p,t])=>`<a href="#${p}" ${location.hash==='#'+p||!location.hash&&p==='start'?'aria-current="page"':''}>${t}</a>`).join('');$('#portal-role').textContent=customer()?'KUNDENPORTAL':partner()?'PARTNERPORTAL':admin()?'ADMINISTRATION':'GUTACHTER-PORTAL';$('#portal-identity').textContent=me.user.name;$('#portal-logout').hidden=!!demo;}
function caseTable(items){if(!items.length)return empty('Hier beginnt deine Fallübersicht.','Sobald ein Fall angelegt oder dir zugewiesen wird, findest du hier alle wichtigen Angaben.',canCreate()?'<a href="#neu" class="btn">Ersten Fall anlegen</a>':'');return `<div class="portal-table-wrap"><table class="portal-table"><thead><tr><th>Vorgang / Fahrzeug</th><th>Status</th><th>${external()?'Unfallort':'Eingereicht von'}</th><th>Aktualisiert</th><th></th></tr></thead><tbody>${items.map(c=>`<tr><td><a href="#fall/${c.id}">${esc(c.number)}</a><small>${esc(c.intake.vehicle)} · ${esc(c.intake.plate)}</small></td><td>${badge(c.status)}</td><td>${esc(external()?c.intake.location:c.companyName)}</td><td>${when(c.updatedAt)}</td><td><a class="portal-button" href="#fall/${c.id}">Öffnen ↗</a></td></tr>`).join('')}</tbody></table></div>`;}
function pending(){return `<div class="portal-alert"><strong>${esc(states[me.company.status])}</strong><p>${me.company.status==='pending'?'Deine E-Mail ist bestätigt. UNFALLX prüft jetzt deine Firmendaten und stimmt die Zusammenarbeit mit dir ab. Danach wird die Falleinreichung freigeschaltet.':'Deine Firma ist aktuell nicht zur Falleinreichung freigeschaltet. Bitte kontaktiere UNFALLX.'}</p>${me.company.reviewNote?'<p>'+esc(me.company.reviewNote)+'</p>':''}<a href="#firma">Firmendaten ansehen →</a></div>`;}
async function dashboard(){cases=(await api('/cases')).cases;const active=cases.filter(c=>!['closed','declined','draft'].includes(c.status)).length;const requests=cases.filter(c=>c.status==='needs_info').length;const done=cases.filter(c=>['report_ready','report_sent','closed'].includes(c.status)).length;const balance=cases.reduce((n,c)=>n+(c.finance?.paymentStatus==='payable'?c.finance.partnerNet:0),0);
root.innerHTML=heading('Guten Tag, '+me.user.name.split(' ')[0]+'.','Alle Vorgänge und nächsten Schritte an einem Ort.',canCreate()?'<a href="#neu" class="btn">+ Neuen Fall anlegen</a>':'')+(partner()&&me.company.status!=='approved'?pending():'')+`<div class="portal-stats"><div class="portal-stat"><span>AKTIVE FÄLLE</span><strong>${active}</strong><small>In gemeinsamer Bearbeitung</small></div><div class="portal-stat"><span>RÜCKFRAGEN</span><strong>${requests}</strong><small>Unterlagen oder Angaben ergänzen</small></div><div class="portal-stat"><span>GUTACHTEN</span><strong>${done}</strong><small>Freigegeben oder versandt</small></div><div class="portal-stat"><span>${partner()?'ABRECHENBAR':'ALLE VORGÄNGE'}</span><strong>${partner()?euro(balance):cases.length}</strong><small>${partner()?'Bestätigte Nettovergütung':'Einschließlich abgeschlossener Fälle'}</small></div></div>${partner()?onboarding():''}<p class="portal-actions"><a class="portal-button" href="#statistik">Statistiken ansehen →</a>${external()?'<a class="portal-button" href="#empfehlungen">UNFALLX empfehlen →</a>':''}</p><section class="portal-card"><h2>Deine aktuellen Vorgänge</h2>${caseTable(cases.slice(0,6))}</section>`;}
async function list(){cases=(await api('/cases')).cases;root.innerHTML=heading('Fallübersicht','Jeder Schritt bleibt mit seinem Vorgang verbunden.','<button class="portal-button" id="export-cases" type="button">Liste als CSV exportieren</button>')+`<section class="portal-card"><div class="portal-toolbar"><input class="portal-filter" id="case-search" placeholder="Fallnummer, Fahrzeug oder Partner suchen" aria-label="Fälle suchen"><select class="portal-filter" id="case-filter" aria-label="Status filtern"><option value="">Alle Status</option>${Object.keys(nextStates).concat(['draft','closed','declined']).map(s=>`<option value="${s}">${states[s]}</option>`).join('')}</select></div><div id="case-results">${caseTable(cases)}</div></section>`;$('#export-cases').addEventListener('click',exportCases);const filter=()=>{const q=$('#case-search').value.toLowerCase(),status=$('#case-filter').value;$('#case-results').innerHTML=caseTable(cases.filter(c=>(!status||c.status===status)&&[c.number,c.companyName,c.intake.vehicle,c.intake.plate,c.intake.location].join(' ').toLowerCase().includes(q)));};$('#case-search').addEventListener('input',filter);$('#case-filter').addEventListener('change',filter);}
function intakeForm(d={}){return `<div class="portal-form-grid">${field('vehicle','Fahrzeug / Modell',d.vehicle)}${field('plate','Kennzeichen',d.plate,'text',true,20)}${field('vin','Fahrgestellnummer (optional)',d.vin,'text',false,17)}${field('accidentDate','Unfalldatum',d.accidentDate,'date')}${field('location','Unfallort',d.location)}${field('owner','Geschädigter / Auftraggeber',d.owner)}${field('ownerContact','Kontakt des Auftraggebers',d.ownerContact,'text',true,200)}${field('customerEmail','E-Mail für Kunden-Statusmeldungen (optional)',d.customerEmail,'email',false,254)}${field('insurer','Versicherung (optional)',d.insurer,'text',false)}${field('claimNumber','Schadennummer (optional)',d.claimNumber,'text',false,120)}${field('lawyerEmail','Beauftragte Kanzlei – E-Mail (optional)',d.lawyerEmail,'email',false,254)}<label class="wide">Unfallhergang, sichtbare Schäden und bekannte Vorschäden<textarea name="description" required maxlength="8000">${esc(d.description)}</textarea></label></div><label class="portal-check"><input name="notifyCustomer" type="checkbox" ${d.notifyCustomer?'checked':''}><span>Der Auftraggeber möchte Statusmeldungen an die angegebene E-Mail-Adresse erhalten. Die Adresse wird vor dem ersten Statusversand per Bestätigungslink geprüft. Für das eigene App-Konto kommen Meldungen automatisch.</span></label><label class="portal-check"><input name="authority" type="checkbox" ${d.authority?'checked':''} required><span>${customer()?'Ich bin zur Weitergabe dieser Angaben und Fotos berechtigt. Falls Daten anderer Personen enthalten sind, sind diese über die Übermittlung informiert.':'Ich bin zur Übermittlung dieser Angaben und Unterlagen berechtigt. Die betroffenen Personen sind informiert; ein entsprechender Auftrag liegt vor.'}</span></label><label class="portal-check"><input name="shareWithLawyer" type="checkbox" ${d.shareWithLawyer?'checked':''}><span>Die Übermittlung des fertigen Gutachtens an die oben benannte Kanzlei ist durch den Auftraggeber autorisiert.</span></label><p class="partner-muted">Bitte keine Gesundheitsdaten oder unnötigen personenbezogenen Angaben übermitteln. Auftragsunterlagen können im nächsten Schritt ergänzt werden.</p>`;}
function newCase(){if(!canCreate()){root.innerHTML=heading('Neuen Fall anlegen')+(partner()?pending():empty('Einreichung durch Partner','Das interne Team übernimmt die eingereichten Fälle.'));return;}root.innerHTML=heading(customer()?'Schaden aufnehmen':'Neuen Fall anlegen','1. Falldaten erfassen · 2. Unterlagen hochladen · 3. Einreichen')+`<div class="portal-card"><form id="case-new">${customer()?'<div class="portal-alert"><strong>Wir prüfen deinen Schaden persönlich.</strong><p>Die Übermittlung ist eine Anfrage. UNFALLX klärt mit dir, ob Fotos ausreichen oder ein Vor-Ort-Termin nötig ist, und stimmt Auftrag und Kosten vor der Gutachtenerstellung ab.</p></div>':''}${intakeForm(customer()?{owner:me.user.name,ownerContact:me.user.email+(me.user.phone?' · '+me.user.phone:'')}: {})}<button class="btn" type="submit">Entwurf speichern und Fotos hinzufügen →</button></form></div>`;bindForm('case-new',async data=>{const r=await api('/cases','POST',data);location.hash='fall/'+r.case.id;});}
function filesHtml(files){return files.length?files.map(f=>{const url=demo&&f.preview?f.preview:'/api/portal/files/'+f.id;return `<div class="portal-file">${f.type.startsWith('image/')?`<img class="portal-photo-thumb" src="${esc(url)}" alt="${esc(f.name)}" width="96" height="72" loading="lazy">`:'<span class="portal-file-icon">PDF</span>'}<div><strong>${esc(f.name)}</strong><small>${esc({photo:'Schadenfoto',document:'Unterlage',report:'Gutachten',partner_invoice:'Partnerrechnung'}[f.kind])} · ${(f.size/1024/1024).toFixed(1)} MB · ${when(f.at)}</small>${demo?'<small>Illustrative Beispielaufnahme, kein echter Auftrag.</small>':''}</div><a href="${esc(url)}" class="portal-button" download>Öffnen</a></div>`;}).join(''):'<p class="partner-muted">Noch keine Unterlagen hinterlegt.</p>';}
function financial(c){if(customer()||c.source==='customer')return '<h2>Direkte Schadenaufnahme</h2><p>UNFALLX prüft Fotos und Angaben fachlich. Auftrag, mögliche Kosten und ein gegebenenfalls notwendiger Besichtigungstermin werden persönlich abgestimmt.</p><a href="/app-hilfe#privatkunden">Anleitung für Privatkunden →</a>';const f=c.finance;if(partner())return `<h2>Deine Vergütung</h2>${!f?'<p>Die Vergütung ist noch nicht vereinbart. UNFALLX hinterlegt die Konditionen nach persönlicher Abstimmung.</p>':`<div class="portal-funds">${euro(f.partnerNet)} <small>netto</small></div><p>${esc(f.agreement)}</p><p class="portal-muted">${esc(payNames[f.paymentStatus])}</p>${!f.partnerAcceptedAt&&f.paymentStatus!=='paid_out'?'<form data-case-action="accept_terms"><label class="portal-check"><input type="checkbox" required><span>Ich bestätige die hier angegebene Vergütungsvereinbarung.</span></label><button class="portal-button" type="submit">Vergütung bestätigen</button></form>':''}${f.paidOutAt?'<p>Auszahlung erfasst: '+when(f.paidOutAt)+'</p>':''}`}`;
if(!admin())return '<h2>Abrechnung</h2><p>Die Administration verwaltet Vergütung, Zahlungseingänge und Auszahlungen.</p>';
return `<h2>Abrechnung verwalten</h2>${f?`<dl class="portal-meta"><div><dt>Gutachtenrechnung brutto</dt><dd>${euro(f.invoiceGross)}</dd></div><div><dt>Zahlungseingang</dt><dd>${euro(f.received)}</dd></div><div><dt>Partnervergütung netto</dt><dd>${euro(f.partnerNet)}</dd></div><div><dt>Partnerbestätigung</dt><dd>${f.partnerAcceptedAt?when(f.partnerAcceptedAt):'Ausstehend'}</dd></div></dl>`:'<p>Noch keine Vergütung hinterlegt. Es gilt keine automatische 50/50-Aufteilung.</p>'}
<details><summary>Rechnung und Vergütung hinterlegen</summary><form data-case-action="finance"><div class="portal-form-grid">${field('invoiceNumber','Rechnungsnummer',f?.invoiceNumber)}${field('invoiceNet','Gutachtenhonorar netto (€)',decimal(f?.invoiceNet))}${field('invoiceGross','Rechnungsbetrag brutto (€)',decimal(f?.invoiceGross))}${field('partnerNet','Vereinbarte Partnervergütung netto (€)',decimal(f?.partnerNet))}<label class="wide">Vereinbarung / Vertragsreferenz<textarea name="agreement" maxlength="1000" required>${esc(f?.agreement)}</textarea></label></div><button class="btn" type="submit">Zur Partnerbestätigung speichern</button></form></details>
${f?`<details><summary>Zahlungseingang erfassen</summary><form data-case-action="payment"><div class="portal-form-grid">${field('amount','Teil- oder Vollzahlung (€)')}${field('date','Buchungsdatum','','date')}${field('reference','Bank- / Buchungsreferenz')}</div><div class="portal-actions"><button class="btn" type="submit">Zahlungseingang verbuchen</button></div></form></details>`:''}
${f?.partnerInvoiceId&&!f.partnerInvoiceApproved?'<form data-case-action="approve_invoice"><label class="portal-check"><input type="checkbox" name="confirmed" required><span>Partnerrechnung geprüft: Empfänger, Leistungsbezug, Nettovergütung, Steuerangaben und Bankverbindung stimmen mit der Vereinbarung überein.</span></label><button class="btn" type="submit">Partnerrechnung freigeben</button></form>':''}
${f?.partnerInvoiceApproved&&!f.paidOutAt?`<form data-case-action="payout"><hr class="portal-separator"><div class="portal-form-grid">${field('date','Auszahlungsdatum','','date')}${field('reference','Überweisungsreferenz')}</div><label class="portal-check"><input type="checkbox" name="confirmed" required><span>Die Banküberweisung wurde tatsächlich ausgeführt. Hier wird sie ausschließlich dokumentiert.</span></label><button class="btn" type="submit">Erfolgte Auszahlung erfassen</button></form>`:''}${f?.paidOutAt?'<p>Auszahlung: '+when(f.paidOutAt)+'</p>':''}`;}
async function detail(cid){current=await api('/cases/'+cid);const c=current.case;let team='';if(admin()){overview=await api('/admin/overview');team=`<form data-case-action="assign"><label>Zuständiger Bearbeiter<select name="assignee" required><option value="">Bitte zuweisen</option>${overview.team.filter(u=>u.active).map(u=>`<option value="${u.id}" ${u.id===c.assignee?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label><div class="portal-actions"><button class="portal-button" type="submit">Zuweisung speichern</button></div></form>`;}
const editable=external()?['draft','needs_info'].includes(c.status):!['closed','declined'].includes(c.status);const canUpload=external()?editable||c.finance?.payable&&!c.finance.partnerInvoiceId:!['closed','declined'].includes(c.status);
root.innerHTML=heading(c.number,c.companyName+' · '+c.intake.vehicle,'<a class="portal-button" href="#faelle">← Alle Fälle</a>')+`<div class="portal-split"><div class="portal-stack"><section class="portal-card"><div class="portal-heading"><h2>Fallakte</h2>${badge(c.status)}</div><dl class="portal-meta">${[['Fahrzeug',c.intake.vehicle],['Kennzeichen',c.intake.plate],['Fahrgestellnummer',c.intake.vin],['Unfallort',c.intake.location],['Unfalldatum',when(c.intake.accidentDate)],['Auftraggeber',c.intake.owner],['Kontakt',c.intake.ownerContact],['Versicherung',c.intake.insurer],['Schadennummer',c.intake.claimNumber],['Kanzlei',c.intake.lawyerEmail]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v||'—')}</dd></div>`).join('')}</dl><hr class="portal-separator"><h3>Schadenbeschreibung</h3><p class="portal-pre">${esc(c.intake.description)}</p>${editable?`<details><summary>Falldaten bearbeiten</summary><form data-case-action="save">${intakeForm(c.intake)}<button type="submit" class="btn">Änderungen speichern</button></form></details>`:''}${external()&&editable?'<form data-case-action="submit"><div class="portal-actions"><button class="btn" type="submit">Fall mit Unterlagen einreichen →</button></div><p class="partner-muted">Nach der Einreichung prüft UNFALLX die Angaben. Ergänzungen sind bei einer Rückfrage möglich.</p></form>':''}</section>
<section class="portal-card"><h2>Fotos &amp; Dokumente</h2>${filesHtml(current.files)}${canUpload?`<form id="file-upload" class="portal-upload"><label>Dateiart<select name="kind">${external()?(editable?'<option value="photo">Schadenfotos</option><option value="document">Auftrag / weitere Unterlagen</option>':'')+(c.finance?.payable&&!c.finance.partnerInvoiceId?'<option value="partner_invoice">Partnerrechnung (PDF)</option>':''):'<option value="report">Fertiges Gutachten (PDF)</option><option value="document">Weitere Unterlagen</option><option value="photo">Ergänzende Fotos</option>'}</select></label><p class="partner-muted">Tipp am Handy: Fotografiere erst das ganze Fahrzeug von vier Seiten, dann Schadenübersicht und Details. Sichere dich und andere vor dem Fotografieren ab.</p><label>Auswählen – bis 6 MB je Datei<input type="file" name="files" multiple accept="image/jpeg,image/png,image/webp,application/pdf" required></label><div class="portal-actions"><button class="portal-button" type="submit">Dateien sicher hochladen</button></div><p class="partner-muted">JPG, PNG, WebP oder PDF. Bis 60 Dateien / 180 MB pro Fall. Originaldateien bleiben erhalten.</p></form>${external()&&editable?'<form id="camera-upload" class="portal-upload"><label>Direkt mit dem Handy fotografieren<input name="photo" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" required></label><button class="portal-button" type="submit">Aufnahme hochladen</button></form>':''}`:''}</section>
<section class="portal-card"><h2>Nachrichten zum Fall</h2><form data-case-action="comment"><label>Nachricht an ${external()?'UNFALLX':'den Einreicher'}<textarea name="note" required maxlength="4000" placeholder="Was soll zum Vorgang geklärt werden?"></textarea></label><div class="portal-actions"><button class="portal-button" type="submit">Nachricht speichern</button></div></form></section></div>
<div class="portal-stack">${!external()?`<section class="portal-card"><h2>Bearbeitung</h2>${team}<hr class="portal-separator">${nextStates[c.status]?`<form data-case-action="status"><label>Nächster Status<select name="status">${nextStates[c.status].map(s=>`<option value="${s}">${states[s]}</option>`).join('')}</select></label><label>Rückfrage / Erläuterung<textarea name="note" maxlength="4000"></textarea></label><label>Bei externem Versand: Empfänger und Versanddatum<input name="reference" maxlength="300"></label><label class="portal-check"><input type="checkbox" name="confirmed"><span>Bei „Gutachten versandt“: Der Versand wurde tatsächlich durchgeführt.</span></label><button class="btn" type="submit">Status aktualisieren</button></form>`:'<p>Der Vorgang ist abgeschlossen.</p>'}
${c.status==='report_ready'&&c.intake.shareWithLawyer&&c.intake.lawyerEmail?`<hr class="portal-separator"><form id="dispatch-form"><h3>An beauftragte Kanzlei senden</h3><p>Empfänger: <strong>${esc(c.intake.lawyerEmail)}</strong></p><label>Freigegebenes Gutachten<select name="fileId">${current.files.filter(f=>f.kind==='report').map(f=>`<option value="${f.id}">${esc(f.name)}</option>`).join('')}</select></label><label class="portal-check"><input type="checkbox" name="confirmed" required><span>Empfänger, Übermittlungsberechtigung und ausgewähltes Gutachten geprüft. Jetzt per E-Mail versenden.</span></label><button class="btn" type="submit">Gutachten verbindlich versenden</button></form>`:''}<details><summary>Interne Notiz</summary><form data-case-action="internal_note"><label>Nur für das UNFALLX-Team<textarea name="note" maxlength="8000">${esc(c.internalNote)}</textarea></label><button class="portal-button" type="submit">Notiz speichern</button></form></details></section>`:''}
<section class="portal-card">${financial(c)}</section><section class="portal-card"><h2>Fallchronik</h2><ol class="portal-timeline">${[...current.events].reverse().map(e=>`<li><strong>${esc(e.action)}${e.internal?' · intern':''}</strong><small>${esc(e.actor)} · ${when(e.at)}</small>${e.note?'<p>'+esc(e.note)+'</p>':''}</li>`).join('')}</ol></section></div></div>`;
root.querySelectorAll('form[data-case-action]').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();run(async()=>{await api('/cases/'+cid,'POST',{...values(form),action:form.dataset.caseAction,version:current.case.version});await detail(cid);message('Änderung gespeichert.');});}));
bindForm('dispatch-form',async d=>{await api('/cases/'+cid+'/dispatch','POST',{...d,version:current.case.version});await detail(cid);message('Gutachten wurde per E-Mail versandt.');});
bindForm('camera-upload',async(d,form)=>{const file=form.elements.photo.files[0];if(!file||file.size>6*1024*1024)throw new Error('Bitte ein Foto bis 6 MB auswählen.');await api('/cases/'+cid+'/files','POST',file,{'Content-Type':file.type,'X-File-Kind':'photo','X-File-Name':encodeURIComponent(file.name)});await detail(cid);message('Foto sicher gespeichert.');});
bindForm('file-upload',async(d,form)=>{const selected=[...form.elements.files.files];let count=0;for(const file of selected)if(file.size>6*1024*1024)throw new Error(file.name+': größer als 6 MB.');for(const file of selected){message(`Datei ${count+1} von ${selected.length} wird hochgeladen …`);await api('/cases/'+cid+'/files','POST',file,{'Content-Type':file.type,'X-File-Kind':d.kind,'X-File-Name':encodeURIComponent(file.name)});count++;}await detail(cid);message(count+' Datei(en) sicher gespeichert.');});}
async function companies(){overview=await api('/admin/overview');root.innerHTML=heading('Partnerfirmen','Firmendaten prüfen, Zusammenarbeit abstimmen und Zugang freigeben.')+overview.companies.map(co=>`<section class="portal-card portal-company"><div class="portal-heading"><div><h2>${esc(co.name)}</h2><p>${esc(co.type)} · ${esc(co.city)}</p></div>${badge(co.status)}</div><dl class="portal-meta">${[['Ansprechpartner',co.contact],['E-Mail',co.email],['Telefon',co.phone],['Anschrift',co.street+', '+co.postcode+' '+co.city],['Steuerangaben',co.taxId],['Register',co.register]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v||'—')}</dd></div>`).join('')}</dl>${co.request?`<div class="portal-alert"><strong>Anfrage der Firma · ${when(co.requestedAt)}</strong><p>${esc(co.request)}</p></div>`:''}<form class="company-review" data-id="${co.id}"><div class="portal-form-grid"><label>Zugang<select name="status">${['pending','approved','rejected','suspended'].map(s=>`<option value="${s}" ${co.status===s?'selected':''}>${states[s]}</option>`).join('')}</select></label><label>Rückmeldung an die Firma<input name="note" maxlength="2000" value="${esc(co.reviewNote)}"></label></div><label class="portal-check"><input type="checkbox" required><span>Firmendaten und erforderliche Vereinbarungen geprüft. Diese Zugangsänderung soll gespeichert werden.</span></label><button class="portal-button" type="submit">Prüfung speichern</button></form></section>`).join('')+(overview.companies.length?'':`<section class="portal-card">${empty('Dein Netzwerk kann starten.','Bestätigte Firmenregistrierungen erscheinen hier zur Prüfung.','<a class="portal-button" href="/mitglied-werden">Partnerseite öffnen ↗</a>')}</section>`);root.querySelectorAll('.company-review').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();run(async()=>{await api('/admin/company','POST',{...values(f),id:f.dataset.id});await companies();message('Partnerstatus gespeichert.');});}));}
async function team(){overview=await api('/admin/overview');root.innerHTML=heading('Internes Team','Zugänge werden ausschließlich von der Administration angelegt.')+`<div class="portal-split"><section class="portal-card"><h2>UNFALLX Zugänge</h2>${overview.team.map(u=>`<div class="portal-file"><div><strong>${esc(u.name)}</strong><small>${esc(u.email)} · ${u.role==='admin'?'Administrator':'Gutachter'} · ${u.active?'Aktiv':'Gesperrt'}${u.role!=='admin'?' · '+(u.verifiedAt?'Einladung angenommen':u.invitationStatus==='failed'?'Einladungsversand fehlgeschlagen':u.invitationSentAt?'Einladung versandt':'Noch nicht angemeldet'):''}</small></div>${u.role!=='admin'&&u.active?`<button type="button" class="portal-button" data-resend="${u.id}">Einladung erneut senden</button>`:''}${u.role!=='admin'?`<button type="button" class="portal-button" data-team="${u.id}" data-active="${!u.active}">${u.active?'Sperren':'Aktivieren'}</button>`:''}</div>`).join('')}</section><section class="portal-card"><h2>Mitarbeiter hinzufügen</h2><form id="team-invite"><div class="portal-form-grid">${field('name','Name')}${field('email','Geschäftliche E-Mail','','email',true,254)}</div><p class="partner-muted">Der interne Gutachter sieht zugewiesene Fälle. Firmenfreigaben und Zahlungsverwaltung bleiben bei der Administration. Beim Anlegen wird eine persönliche Einladung per E-Mail verschickt. Sie ist 24 Stunden gültig.</p><button class="btn" type="submit">Zugang anlegen &amp; Einladung senden</button></form></section></div>`;bindForm('team-invite',async d=>{const r=await api('/admin/invite','POST',d);await team();message(r.message,r.invitationSent===false);});root.querySelectorAll('[data-resend]').forEach(b=>b.addEventListener('click',()=>run(async()=>{const r=await api('/admin/resend-invitation','POST',{id:b.dataset.resend});await team();message(r.message,r.invitationSent===false);})));root.querySelectorAll('[data-team]').forEach(b=>b.addEventListener('click',()=>run(async()=>{await api('/admin/team','POST',{id:b.dataset.team,active:b.dataset.active==='true'});await team();message('Zugang aktualisiert.');})));}
async function billing(){cases=(await api('/cases')).cases.filter(c=>c.source!=='customer');root.innerHTML=heading('Abrechnung','Individuell vereinbart. Nach Zahlungseingang nachvollziehbar abgerechnet.')+`<section class="portal-card"><p class="partner-muted">Es gibt keine automatische Vergütungsquote. Pro Fall werden die Konditionen festgehalten und vom Partner bestätigt. Die Rechnung wird erst nach vollständigem Zahlungseingang und Gutachtenversand freigeschaltet.</p><div class="portal-table-wrap"><table class="portal-table"><thead><tr><th>Vorgang</th><th>Partnervergütung netto</th><th>Stand</th><th></th></tr></thead><tbody>${cases.map(c=>`<tr><td>${esc(c.number)}<small>${esc(c.intake.vehicle)}</small></td><td>${c.finance?euro(c.finance.partnerNet):'Noch offen'}</td><td>${partner()?esc(payNames[c.finance?.paymentStatus||'unset']):c.finance?.paidOutAt?'Auszahlung erfasst':c.finance?.partnerInvoiceApproved?'Auszahlung freigegeben':c.finance?.partnerInvoiceId?'Partnerrechnung prüfen':c.finance?euro(c.finance.received)+' / '+euro(c.finance.invoiceGross)+' bezahlt':'Noch nicht vereinbart'}</td><td><a class="portal-button" href="#fall/${c.id}">Details ↗</a></td></tr>`).join('')}</tbody></table></div>${cases.length?'':empty('Noch keine Abrechnungen','Die vereinbarte Vergütung erscheint beim jeweiligen Fall.')}</section>`;}
function company(){const co=me.company;root.innerHTML=heading('Meine Firma','Deine Stammdaten und Ansprechpartner bei UNFALLX.')+`<div class="portal-split"><section class="portal-card"><h2>${esc(co.name)}</h2>${badge(co.status)}<dl class="portal-meta">${[['Ansprechpartner',co.contact],['E-Mail',co.email],['Telefon',co.phone],['Anschrift',co.street+', '+co.postcode+' '+co.city],['Unternehmensart',co.type]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p class="partner-muted">Änderungen an Firmendaten oder eine Datenschutzanfrage kannst du hier an die Administration übermitteln.</p><button class="portal-button" id="export-data" type="button">Meine Daten exportieren</button></section><section class="portal-card"><h2>Änderung oder Anfrage</h2><form id="company-request"><label>Deine Nachricht<textarea name="request" required maxlength="4000" placeholder="Zum Beispiel: neue Firmenanschrift oder Bitte um Löschung …"></textarea></label><div class="portal-actions"><button class="btn" type="submit">Anfrage übermitteln</button></div></form>${co.request?'<p class="partner-muted">Letzte Anfrage: '+esc(co.request)+'</p>':''}</section></div>`;bindForm('company-request',async d=>{const r=await api('/profile','POST',d);message(r.message);});$('#export-data').addEventListener('click',()=>run(async()=>{const data=await api('/export');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='UNFALLX-meine-Daten.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}));}
function onboarding(){const co=me.company;const first=cases.length>0,submitted=cases.some(c=>c.status!=='draft');return `<section class="portal-card portal-onboarding"><h2>Dein Start mit UNFALLX</h2><ol><li data-done="true"><strong>1. E-Mail bestätigt</strong><span>Dein persönlicher Zugang ist aktiv.</span></li><li data-done="${co.status==='approved'}"><strong>2. Betrieb freischalten</strong><span>${co.status==='approved'?'UNFALLX hat deinen Betrieb freigeschaltet.':'Wir prüfen deine Angaben und stimmen die Zusammenarbeit ab.'}</span></li><li data-done="${first}"><strong>3. Ersten Fall anlegen</strong><span>Fahrzeug, Unfallhergang und Auftrag erfassen.</span></li><li data-done="${submitted}"><strong>4. Mit Fotos einreichen</strong><span>Unterlagen prüfen und an UNFALLX übergeben.</span></li></ol><a href="/app-hilfe#erster-fall" target="_blank" rel="noopener">Schritt für Schritt ansehen ↗</a></section>`;}
function exportCases(){const cell=v=>{let s=String(v??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const rows=[['Fallnummer','Fahrzeug','Kennzeichen','Status','Unfallort','Aktualisiert'],...cases.map(c=>[c.number,c.intake.vehicle,c.intake.plate,states[c.status],c.intake.location,c.updatedAt])];const url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='UNFALLX-Falluebersicht.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('Die Fallübersicht wurde als CSV exportiert.');}
async function settings(){const data=await api('/settings');const identities=demo?{providers:[],linked:[]}:await api('/identities');const p=data.preferences;root.innerHTML=heading('Einstellungen','Dein Profil, deine Ansicht und dein sicherer Zugang.')+`<div class="portal-split"><section class="portal-card"><h2>Profil &amp; Darstellung</h2><form id="settings-form"><div class="portal-form-grid">${field('name','Dein Name',data.profile.name)}${field('phone','Telefon (optional)',data.profile.phone,'tel',false,40)}${field('jobTitle','Funktion (optional)',data.profile.jobTitle,'text',false,100)}<label>E-Mail-Adresse<input value="${esc(data.profile.email)}" type="email" disabled><small>Für eine Änderung kontaktiere UNFALLX.</small></label><label>Startansicht<select name="startPage"><option value="start" ${p.startPage==='start'?'selected':''}>Übersicht</option><option value="faelle" ${p.startPage==='faelle'?'selected':''}>Fallübersicht</option></select></label><label>Darstellung<select name="theme"><option value="light" ${p.theme!=='dark'?'selected':''}>Hell</option><option value="dark" ${p.theme==='dark'?'selected':''}>Dunkel</option></select></label></div><label class="portal-check"><input type="checkbox" name="compact" ${p.compact?'checked':''}><span>Kompakte Tabellen mit geringeren Zeilenabständen</span></label><label class="portal-check"><input type="checkbox" name="reducedMotion" ${p.reducedMotion?'checked':''}><span>Bewegungen und weiches Scrollen reduzieren</span></label><label class="portal-check"><input name="caseEmails" type="checkbox" ${p.caseEmails!==false?'checked':''}><span>E-Mail bei Falländerungen erhalten. Sicherheits- und Zugangs-E-Mails bleiben aktiv.</span></label><button class="btn" type="submit">Einstellungen speichern</button></form></section><div class="portal-stack"><section class="portal-card"><h2>Zugang &amp; Sicherheit</h2><p><strong>${data.activeSessions}</strong> aktive Sitzung(en). Deine aktuelle Anmeldung läuft spätestens nach zwölf Stunden ab.</p><p>${me.user.hasPassword?'Dein persönliches Passwort ist eingerichtet.':'Für dein bestehendes Konto kannst du jetzt ein eigenes Passwort festlegen.'}</p><p><a href="/passwort" class="portal-button">Passwort festlegen / zurücksetzen</a></p><div class="portal-identity-list">${identities.providers.map(p=>`<div><strong>${p.name}</strong> · ${identities.linked.includes(p.id)?'Verbunden':p.enabled?'Verfügbar':'Einrichtung ausstehend'}<button type="button" class="portal-button" data-provider="${p.id}" data-linked="${identities.linked.includes(p.id)}" ${p.enabled?'':'disabled'}>${identities.linked.includes(p.id)?'Verbindung trennen':'Konto verbinden'}</button></div>`).join('')}</div><small>Zum Verbinden oder Trennen muss deine Anmeldung weniger als 15 Minuten zurückliegen.</small><form id="revoke-sessions"><label class="portal-check"><input name="confirmed" type="checkbox" required><span>Alle anderen Geräte abmelden. Dieses Gerät bleibt angemeldet.</span></label><button class="portal-button" type="submit">Andere Geräte abmelden</button></form></section>${data.storage?`<section class="portal-card"><h2>Dokumentenspeicher</h2><strong>${(data.storage.used/1024/1024).toFixed(1)} / ${(data.storage.limit/1024/1024).toFixed(0)} MB</strong><progress max="${data.storage.limit}" value="${data.storage.used}" aria-label="Belegter Dokumentenspeicher"></progress><p>Fotos und Dokumente bleiben privat. Bei zusätzlichem Speicherbedarf den Hosting-Ausbau vorab planen.</p></section>`:''}<section class="portal-card"><h2>Unterstützung</h2><p>Fragen zur Registrierung, zu Unterlagen oder zur Abrechnung?</p><a href="/app-hilfe">Hilfe öffnen →</a>${partner()?'<p><a href="#firma">Firmendaten ansehen oder Änderung anfragen →</a></p>':''}</section></div></div>`;document.querySelectorAll('[data-provider]').forEach(b=>b.addEventListener('click',()=>run(async()=>{if(b.dataset.linked==='true'){await api('/identities/unlink','POST',{provider:b.dataset.provider});await settings();message('Verbindung getrennt.');}else{const r=await api('/oauth/start','POST',{provider:b.dataset.provider,link:true});location.assign(r.redirect);}})));bindForm('settings-form',async d=>{const r=await api('/settings','POST',d);me.user=r.user;appearance();navigation();message(r.message);});bindForm('revoke-sessions',async d=>{const r=await api('/sessions/revoke-others','POST',d);await settings();message(r.message);});}
function help(){root.innerHTML=heading('Hilfe & Anleitung','Von der Registrierung bis zur nachvollziehbaren Abrechnung.')+`<section class="portal-card"><h2>Welchen Schritt möchtest du ansehen?</h2><div class="portal-help-grid"><a href="/app-hilfe#privatkunden">Privatkunden · Schaden selbst aufnehmen</a><a href="/app-hilfe#bildung-hilfe">Bildung · Anmeldung &amp; Kursplatz</a><a href="/app-hilfe#registrierung">01 · Registrierung &amp; Login</a><a href="/app-hilfe#erster-fall">02 · Deinen ersten Fall anlegen</a><a href="/app-hilfe#fotos">03 · Fotos &amp; Dokumente hochladen</a><a href="/app-hilfe#bearbeitung">04 · Bearbeitungsstatus verstehen</a><a href="/app-hilfe#abrechnung">05 · Vergütung &amp; Partnerrechnung</a><a href="/app-hilfe#team">06 · Internes Team verwalten</a></div><p>Die ausführliche Anleitung enthält echte Ansichten der App mit fiktiven Beispieldaten.</p><div class="portal-actions"><a class="btn" href="/app-hilfe">Zur vollständigen Hilfe</a><a class="portal-button" href="/app-demo">Beispielfälle ansehen</a></div></section><section class="portal-card"><h2>Wir sind persönlich erreichbar.</h2><p><a href="mailto:info@unfallx.com">info@unfallx.com</a> · <a href="tel:+4917664365185">0176 64 365 185</a></p><p>Nenne bei Rückfragen deine Fallnummer. Passwörter, persönliche Login-Links und Zugangsdaten bitte niemals weitergeben.</p></section>`;}

async function education(){
 const data=await api('/admin/academy');
 const names={requested:'Vorgemerkt',confirmed:'Platz bestätigt',waitlisted:'Warteliste',cancelled:'Storniert',interest:'Digitales Interesse'};
 root.innerHTML=heading('Bildungsanmeldungen','Berlin · eine Woche · maximal 26 Vormerk- und bestätigte Plätze je Kurswoche.','<a class="portal-button" href="/bildung" target="_blank" rel="noopener">Öffentliche Kursseite ↗</a>')+`<section class="portal-card"><h2>Kursplanung &amp; Auslastung</h2><p><strong>1.500 € pro Person.</strong> ${data.schedule?'Veröffentlichter Start: '+when(data.schedule.start)+'.':'Starttermin wird demnächst bekannt gegeben.'}</p>${!data.schedule?'<form id="course-schedule"><label>Ersten Kursstart veröffentlichen (Montag)<input name="start" type="date" required></label><label class="portal-check"><input type="checkbox" required><span>Dieser Starttermin steht fest und darf öffentlich angezeigt werden.</span></label><button class="portal-button" type="submit">Starttermin veröffentlichen</button></form>':''}<p>Stimme Durchführung, Lernort und Zeiten persönlich ab, bevor du eine Teilnahme zusagst. Statusänderungen lösen eine E-Mail an den Interessenten aus. Digitale Kurse sind noch nicht buchbar.</p><div class="portal-help-grid">${data.weeks.map(w=>`<div>${when(w.week)}<br><strong>${w.reserved} / ${w.capacity}</strong> vorgemerkt / bestätigt · ${w.waitlisted} Warteliste</div>`).join('')}</div></section><section class="portal-card"><div class="portal-toolbar"><label>Anmeldungen filtern<input id="education-search" placeholder="Name, E-Mail oder Kurswoche"></label><label>Status<select id="education-status"><option value="">Alle Status</option>${Object.entries(names).map(([v,n])=>`<option value="${v}">${n}</option>`).join('')}</select></label><button id="education-export" class="portal-button" type="button">Teilnehmerliste als CSV</button></div><div id="education-results"></div></section>`;
 bindForm('course-schedule',async d=>{const result=await api('/admin/academy','POST',{action:'schedule',start:d.start});await education();message(result.message);});
 let shown=data.registrations;
 function paint(){const q=$('#education-search').value.toLowerCase(),status=$('#education-status').value;shown=data.registrations.filter(r=>(!status||r.status===status)&&[r.name,r.email,r.week,r.phone].join(' ').toLowerCase().includes(q));$('#education-results').innerHTML=shown.map(r=>`<article class="portal-card"><h2>${esc(r.name)}</h2><p>${r.mode==='digital'?'Digital · demnächst':when(r.week)+' · Berlin'} · <strong>${names[r.status]}</strong></p><p><a href="mailto:${esc(r.email)}">${esc(r.email)}</a> · ${esc(r.phone)}</p><p class="portal-pre">${esc(r.background||'Keine Vorkenntnisse angegeben.')}</p>${r.notification==='failed'?'<p class="portal-error">Letzte E-Mail nicht versandt. Status erneut speichern, um den Versand zu wiederholen.</p>':''}<form data-course="${esc(r.id)}"><label>Status<select name="status">${(r.mode==='digital'?['interest','cancelled']:['requested','confirmed','waitlisted','cancelled']).map(v=>`<option value="${v}" ${r.status===v?'selected':''}>${names[v]}</option>`).join('')}</select></label><label>Interne Notiz<textarea name="note" maxlength="2000">${esc(r.note||'')}</textarea></label><label class="portal-check"><input type="checkbox" required><span>Diese Änderung speichern und den Interessenten per E-Mail informieren.</span></label><button class="portal-button" type="submit">Status speichern &amp; informieren</button></form></article>`).join('')||empty('Noch keine passenden Anmeldungen.','Bestätigte Anfragen erscheinen hier automatisch.');$('#education-results').querySelectorAll('[data-course]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();run(async()=>{const result=await api('/admin/academy','POST',{...values(f),id:f.dataset.course});await education();message(result.message,!result.notificationSent);});}));}
 $('#education-search').addEventListener('input',paint);$('#education-status').addEventListener('change',paint);paint();
 $('#education-export').addEventListener('click',()=>{const cell=v=>'"'+String(v||'').replace(/^[\s]*[=+@-]/,"' $&").replace(/"/g,'""')+'"';const rows=[['Name','E-Mail','Telefon','Format','Wunschwoche','Status'],...shown.map(r=>[r.name,r.email,r.phone,r.mode,r.week,names[r.status]])];const url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='UNFALLX-Bildungsanmeldungen.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
}


async function stats(){const d=await api('/statistics');root.innerHTML=heading('Deine Statistiken',d.scope+'. Berechnet aus den im Portal erfassten Vorgängen.')+`<div class="portal-stats"><div class="portal-stat"><span>VORGÄNGE</span><strong>${d.total}</strong><small>Alle erfassten Fälle</small></div><div class="portal-stat"><span>IN BEARBEITUNG</span><strong>${d.active}</strong><small>Offene Vorgänge ohne Entwürfe</small></div><div class="portal-stat"><span>GUTACHTEN</span><strong>${d.reports}</strong><small>Freigegeben oder versandt</small></div><div class="portal-stat"><span>BIS ZUR FREIGABE</span><strong>${d.averageDays===null?'—':d.averageDays+' T.'}</strong><small>${d.durationSample} Fälle mit erfasster Einreichung und Freigabe</small></div></div><div class="portal-split"><section class="portal-card"><h2>Bearbeitungsstand</h2>${d.groups.map(g=>`<div class="stat-bar"><div><span>${esc(g.label)}</span><strong>${g.count}</strong></div><progress max="${Math.max(1,d.total)}" value="${g.count}" aria-label="${esc(g.label)}: ${g.count} von ${d.total}"></progress></div>`).join('')}</section><section class="portal-card"><h2>Die letzten sechs Monate</h2><div class="portal-table-wrap"><table class="portal-table"><thead><tr><th>Monat</th><th>Angelegt</th><th>Erstmals freigegeben</th></tr></thead><tbody>${d.months.map(m=>`<tr><td>${esc(m.month)}</td><td>${m.created}</td><td>${m.reports}</td></tr>`).join('')}</tbody></table></div><p>Freigabezeiten werden ab Einführung dieser Statistik erfasst. Ältere Fälle ohne Zeitstempel fließen nicht in den Durchschnitt ein. Zeiten sind Kalendertage und keine zugesagte Bearbeitungsdauer.</p><a href="#faelle">Zu deinen Fällen →</a></section></div>`;}
const rewardNames={review:'In Prüfung',offered:'Vereinbarung angeboten',approved:'Vereinbart · Abrechnung abstimmen',paid:'Auszahlung erfasst',rejected:'Nicht vergütungsfähig'};
async function referrals(){const d=await api('/referrals');root.innerHTML=heading('UNFALLX empfehlen','Dein Netzwerk. Ein nachvollziehbarer Empfehlungsweg.')+`<section class="portal-card"><h2>Dein persönlicher Empfehlungslink</h2><p>Empfiehl UNFALLX Connect an neue Kunden oder Betriebe. Der Empfehlungscode wird bei der Neuregistrierung zugeordnet. Vergütungsfähige Gutachten werden anschließend einzeln geprüft. Es gibt keinen pauschalen oder garantierten Provisionsbetrag.</p>${d.url?`<label>Link zum Weitergeben<input id="referral-url" readonly value="${esc(d.url)}"></label><button id="copy-referral" type="button" class="btn">Link kopieren</button><p>${d.referredAccounts} bestätigte Registrierung(en) über deinen Code.</p>`:`<form id="referral-join"><label class="portal-check"><input name="accepted" type="checkbox" required><span>Ich akzeptiere die <a href="/empfehlungsbedingungen" target="_blank" rel="noopener">Empfehlungsbedingungen</a>. Selbstempfehlungen sind ausgeschlossen. Vergütungen werden individuell angeboten und vereinbart.</span></label><button type="submit" class="btn">Empfehlungslink aktivieren</button></form>`}</section><div class="portal-stats"><div class="portal-stat"><span>ANGEBOTEN</span><strong>${euro(d.totals.offered)}</strong><small>Noch von dir zu bestätigen</small></div><div class="portal-stat"><span>VEREINBART</span><strong>${euro(d.totals.approved)}</strong><small>Abrechnung / Auszahlung offen</small></div><div class="portal-stat"><span>AUSGEZAHLT</span><strong>${euro(d.totals.paid)}</strong><small>Dokumentierte Überweisungen</small></div></div><section class="portal-card"><h2>Deine Empfehlungen &amp; Provisionen</h2><p>Du siehst ausschließlich deine Provisionsvorgänge. Kunden, Kennzeichen und Schadenunterlagen anderer Personen bleiben vertraulich.</p>${d.rewards.length?d.rewards.map(r=>`<article class="referral-reward"><div><strong>${esc(r.reference)}</strong><span>${rewardNames[r.state]}</span></div><h3>${r.amount?euro(r.amount):'Betrag noch offen'}</h3><p>${esc(r.agreement||'UNFALLX prüft den abgeschlossenen Vorgang und eine mögliche Vergütung.')}</p>${r.state==='offered'?`<form data-reward-accept="${r.id}"><label class="portal-check"><input name="accepted" type="checkbox" required><span>Ich akzeptiere diese Einzelvereinbarung.</span></label><button class="portal-button" type="submit">Vereinbarung bestätigen</button></form>`:''}${r.paidAt?'<p>Auszahlung erfasst am '+when(r.paidAt)+'</p>':''}</article>`).join(''):empty('Noch keine Provisionsvorgänge.','Nach einem zugeordneten Gutachtenabschluss erscheint die Prüfung hier.')}</section>`;
 bindForm('referral-join',async values=>{await api('/referrals/join','POST',values);await referrals();});const copy=$('#copy-referral');if(copy)copy.addEventListener('click',()=>run(async()=>{try{await navigator.clipboard.writeText(d.url);message('Empfehlungslink kopiert.');}catch{$('#referral-url').select();message('Markierten Link bitte kopieren.');}}));document.querySelectorAll('[data-reward-accept]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();run(async()=>{const r=d.rewards.find(r=>r.id===f.dataset.rewardAccept);await api('/referrals/accept','POST',{...values(f),id:r.id,version:r.version});await referrals();message('Vereinbarung bestätigt.');});}));}
async function commissions(){const d=await api('/admin/referrals');root.innerHTML=heading('Empfehlungsprovisionen','Einzelvereinbarungen und Auszahlungen nachvollziehbar erfassen.')+`<section class="portal-card"><p>${d.attributions} zugeordnete Registrierung(en). Ein Provisionsvorgang entsteht erst, wenn ein zugeordnetes Gutachten versandt oder abgeschlossen ist.</p><p>Prüfe Empfehlung, Auftrag, vollständigen Zahlungseingang und Abrechnungsbeleg. Die App führt keine Banküberweisungen aus.</p>${d.rewards.length?d.rewards.map(r=>`<details class="commission-item"><summary>${esc(r.reference)} · ${esc(r.referrerName)} · ${rewardNames[r.state]} · ${r.amount?euro(r.amount):'offen'}</summary><p>Fall ${esc(r.caseNumber)} · ${esc(states[r.caseStatus])} · ${esc(r.referrerEmail)}</p><p>${esc(r.agreement)}</p>${['review','offered','rejected'].includes(r.state)?`<form data-commission="${r.id}" data-action="offer"><div class="portal-form-grid">${field('amount','Provisionsbetrag in Euro',r.amount?decimal(r.amount):'')}${field('settledGross','Vollständig bezahltes Brutto-Gutachtenhonorar in Euro',r.settledGross?decimal(r.settledGross):'')}${field('invoiceReference','Gutachten-Rechnungsnummer',r.invoiceReference||'')}${field('paymentReference','Zahlungseingang: Datum / Buchungsreferenz',r.paymentReference||'')}</div><label>Individuelle Vergütungsvereinbarung einschließlich Steuer-/Abrechnungsgrundlage<textarea name="agreement" required maxlength="2000">${esc(r.agreement)}</textarea></label><label class="portal-check"><input name="paymentConfirmed" type="checkbox" required><span>Gutachtenauftrag, Empfehlung und vollständigen Zahlungseingang geprüft.</span></label><button class="btn" type="submit">Vereinbarung anbieten</button></form>`:''}${r.state==='review'||r.state==='offered'?`<form data-commission="${r.id}" data-action="reject"><label>Begründung der Ablehnung<textarea name="reason" required maxlength="2000"></textarea></label><button type="submit" class="portal-button">Nicht vergütungsfähig markieren</button></form>`:''}${r.state==='approved'?`<form data-commission="${r.id}" data-action="paid">${field('date','Datum der erfolgten Überweisung','','date')}${field('reference','Bank-Buchungsreferenz')}${field('receiptReference','Geprüfte Rechnung / Abrechnungsbeleg')}<label class="portal-check"><input name="confirmed" type="checkbox" required><span>Beleg geprüft und vereinbarten Betrag bereits überwiesen.</span></label><button class="btn" type="submit">Erfolgte Auszahlung dokumentieren</button></form>`:''}${r.state==='paid'?'<p>Erfasste Auszahlung: '+when(r.paidAt)+' · '+esc(r.payoutReference)+' · Beleg: '+esc(r.receiptReference)+'</p>':''}</details>`).join(''):empty('Noch keine abgeschlossenen Empfehlungen.','Die Prüfung erscheint nach einem zugeordneten Gutachtenabschluss.')}</section>`;document.querySelectorAll('[data-commission]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();run(async()=>{const r=d.rewards.find(r=>r.id===f.dataset.commission);await api('/admin/referrals','POST',{...values(f),id:r.id,version:r.version,action:f.dataset.action});await commissions();message('Provision gespeichert.');});}));}
async function delivery(){const d=await api('/admin/notifications'),auth=await api('/admin/auth-status');const labels={pending:'Wartet auf Versand',sending:'Wird versandt',sent:'Vom Mailserver angenommen',uncertain:'Zustellung prüfen',cancelled:'Nicht mehr erforderlich'};root.innerHTML=heading('E-Mail-Versand','Statusmeldungen zu Fällen und Bestätigungen für zusätzliche Kundenadressen.','<button type="button" class="portal-button" id="refresh-delivery">Aktualisieren</button>')+`<section class="portal-card"><h2>Anmeldemethoden</h2>${auth.providers.map(p=>`<p><strong>${p.name}</strong> · ${p.enabled?'Server-Konfiguration vorhanden – Anbieter-Anmeldung testen':'Einrichtung der Anbieter-Zugangsdaten ausstehend'}</p><p class="portal-url">Rücksprungadresse: ${esc(auth.callbacks[p.id])}</p>`).join('')}<p>SMTP-Annahme ist keine Lesebestätigung. Bei unklarem Versand vor einer Wiederholung Empfänger und Postausgang prüfen.</p></section><section class="portal-card">${d.notifications.length?d.notifications.map(n=>`<article class="delivery-item"><strong>${esc(n.subject)}</strong><p>${esc(n.to)} · ${when(n.createdAt)}<br>${labels[n.state]} · ${n.attempts} Versuch(e)</p>${n.lastError?'<p>'+esc(n.lastError)+'</p>':''}${n.state==='uncertain'?`<form data-retry-mail="${n.id}"><label class="portal-check"><input name="confirmed" type="checkbox" required><span>Zustellung geprüft; eine erneute E-Mail ist erforderlich.</span></label><button type="submit" class="portal-button">Versand erneut freigeben</button></form>`:''}</article>`).join(''):empty('Noch keine Fallbenachrichtigungen.','Neue Falländerungen erscheinen automatisch hier.')}</section>`;$('#refresh-delivery').addEventListener('click',()=>run(delivery));document.querySelectorAll('[data-retry-mail]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();run(async()=>{await api('/admin/notifications/retry','POST',{...values(f),id:f.dataset.retryMail});await delivery();message('Nachricht zum Versand freigegeben.');});}));}

async function render(){message('');navigation();const route=location.hash.slice(1)||'start';if(route==='start')await dashboard();else if(route==='statistik')await stats();else if(route==='empfehlungen'&&external())await referrals();else if(route==='provisionen'&&admin())await commissions();else if(route==='versand'&&admin())await delivery();else if(route==='einstellungen')await settings();else if(route==='hilfe')help();else if(route==='faelle')await list();else if(route==='neu')newCase();else if(route==='firma'&&partner())company();else if(route==='partner'&&admin())await companies();else if(route==='team'&&admin())await team();else if(route==='bildung'&&admin())await education();else if(route==='abrechnung'&&(admin()||partner()))await billing();else if(/^fall\/[a-f0-9-]{36}$/.test(route))await detail(route.split('/')[1]);else{location.hash='start';}window.scrollTo({top:0});}
async function boot(){try{me=await api('/me');csrf=me.csrf;appearance();if(!location.hash&&me.user.preferences?.startPage==='faelle')history.replaceState(null,'',location.pathname+'#faelle');const target=customer()?'/kundenportal':partner()?'/portal':'/gutachter-portal';if(!demo&&location.pathname!==target)history.replaceState(null,'',target+location.hash);if(demo){$('#portal-role').textContent='BEISPIELANSICHT';}await render();}catch(e){if(e.status===401){location.replace('/login');return;}root.innerHTML=empty('Das Portal ist gerade nicht erreichbar.',e.message,'<a href="/login" class="portal-button">Zur Anmeldung</a>');}}
$('#portal-logout').addEventListener('click',()=>run(async()=>{await api('/logout','POST',{});location.replace('/login');}));
window.addEventListener('hashchange',()=>run(render));boot();
})();
